// This code snippet demonstrates the importance of cultural sensitivity in software development.

// Function to display a culturally sensitive greeting
function displayGreeting(userCulture) {
    let greeting;

    // Determine greeting based on user's cultural background
    switch (userCulture) {
        case 'Japanese':
            greeting = 'こんにちは'; // Hello in Japanese
            break;
        case 'Spanish':
            greeting = 'Hola'; // Hello in Spanish
            break;
        case 'French':
            greeting = 'Bonjour'; // Hello in French
            break;
        default:
            greeting = 'Hello'; // Default to English
    }

    console.log(greeting);
}

// Example usage
displayGreeting('Japanese'); // Outputs: こんにちは
displayGreeting('Spanish');  // Outputs: Hola
displayGreeting('French');   // Outputs: Bonjour
displayGreeting('English');  // Outputs: Hello

