// This code checks if a person is hypocritical based on their actions and statements
function isHypocritical(actions, statements) {
    for (let i = 0; i < actions.length; i++) {
        if (actions[i] !== statements[i]) {
            return true; // The person is hypocritical
        }
    }
    return false; // The person is not hypocritical
}

// Example usage
const actions = ['say one thing', 'do another'];
const statements = ['say one thing', 'do the same thing'];

console.log(isHypocritical(actions, statements)); // Output: true

