// SelfRelianceVsEntitlement
// This code snippet explores the concept of self-reliance versus entitlement.
// It aims to demonstrate the importance of personal responsibility and the potential pitfalls of expecting others to provide for one's needs.

class Individual {
    constructor(name, selfRelianceScore, entitlementScore) {
        this.name = name;
        this.selfRelianceScore = selfRelianceScore;
        this.entitlementScore = entitlementScore;
    }

    evaluateMindset() {
        if (this.selfRelianceScore > this.entitlementScore) {
            return `${this.name} is more self-reliant.`;
        } else if (this.entitlementScore > this.selfRelianceScore) {
            return `${this.name} has a higher sense of entitlement.`;
        } else {
            return `${this.name} has a balanced mindset.`;
        }
    }
}

// Example usage:
const person1 = new Individual('Alice', 8, 3);
console.log(person1.evaluateMindset()); // Output: Alice is more self-reliant.

const person2 = new Individual('Bob', 4, 6);
console.log(person2.evaluateMindset()); // Output: Bob has a higher sense of entitlement.

const person3 = new Individual('Charlie', 5, 5);
console.log(person3.evaluateMindset()); // Output: Charlie has a balanced mindset.

