// This code snippet handles the event of a party affiliation change for a user.

function handlePartyAffiliationChange(userId, newAffiliation) {
    // Log the change for auditing purposes
    console.log(`User ${userId} changed party affiliation to ${newAffiliation}.`);

    // Update the user's profile with the new party affiliation
    updateUserProfile(userId, { partyAffiliation: newAffiliation });

    // Notify the user of the successful change
    notifyUser(userId, `Your party affiliation has been updated to ${newAffiliation}.`);
}

function updateUserProfile(userId, updates) {
    // Simulate updating the user's profile in a database
    console.log(`Updating user ${userId} profile with:`, updates);
}

function notifyUser(userId, message) {
    // Simulate sending a notification to the user
    console.log(`Notification to user ${userId}: ${message}`);
}

// Example usage
handlePartyAffiliationChange(12345, 'Independent');

