# Qualitative code for refining summaries

def refine_summaries(summaries):
    refined_summaries = []
    for summary in summaries:
        if concealed carry in summary.lower():
            refined_summaries.append(Concealed carry reduces visibility, eliminating concern.)
        elif mental health in summary.lower():
            refined_summaries.append(Mental health issues result in legal restrictions on firearm ownership.)
        elif constitutional rights in summary.lower():
            refined_summaries.append(Opposition to any infringement on constitutional rights.)
        elif gun show loophole in summary.lower():
            refined_summaries.append(No gun show loophole; background checks are mandatory.)
        elif psychiatric evaluation in summary.lower():
            refined_summaries.append(Unreasonable fear of objects warrants psychiatric evaluation.)
    return refined_summaries

# Example usage
summaries = [
    The first summary is about concealed carry reducing visibility and thus concern.,
    The second summary mentions mental health issues leading to a firearm ban.,
    The third summary is about opposing constitutional right infringements.,
    The fourth summary clarifies the gun show loophole and background checks.,
    The fifth summary suggests psychiatric evaluation for unreasonable fear.
]

refined = refine_summaries(summaries)
for r in refined:
    print(r)

